-- Biochemistry Ch1: Amino Acids, Peptides, and Proteins — BATCH 3 (Peptide Bonds + Primary/Secondary Structure)
-- discipline=biochemistry, foundation=1A. Safe to re-run: deletes only this batch's subtopics.

DELETE FROM questions WHERE topic = 'Amino Acids, Peptides, and Proteins' AND subtopic IN ('Peptide Bond Formation & Hydrolysis', 'Primary Structure', 'Secondary Structure (α-helix & β-sheet)');

-- Q1 [Peptide Bond Formation & Hydrolysis] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Peptide Bond Formation & Hydrolysis', 'During protein synthesis, a ribosome joins the \(\alpha\)-carboxyl group of one amino acid to the \(\alpha\)-amino group of the next, forming a peptide bond. As this single new bond forms, the reaction releases which of the following molecules?', '[{"label": "A", "text": "A molecule of ATP"}, {"label": "B", "text": "A molecule of water"}, {"label": "C", "text": "A free phosphate group"}, {"label": "D", "text": "A hydrogen ion only"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because a peptide bond is an amide linkage formed by dehydration synthesis (condensation), in which the \(\alpha\)-carboxyl of one amino acid joins the \(\alpha\)-amino of the next and one molecule of \(\text{H}_2\text{O}\) is released. LibreTexts states the amino group attacks the electrophilic carbonyl carbon and "In this reaction, water is released," and that "The amino acids are linked together using dehydration synthesis (loss of water) reaction." OpenStax likewise notes the two groups "combine, releasing a water molecule." The reverse reaction, hydrolysis, consumes water to break the bond. (Choice A) is incorrect: ATP is hydrolyzed to activate the carboxyl group before the bond forms, but it is not the molecule released as the amide bond itself is created. (Choice B) is correct: forming the amide (peptide) bond is a condensation that expels exactly one molecule of water per bond. (Choice C) is incorrect: the activation step uses ATP and produces a phosphate-containing intermediate, but the dehydration synthesis that makes the peptide bond releases water, not free phosphate. (Choice D) is incorrect: the released water can be viewed as -OH from the carboxyl plus -H from the amine, but the net byproduct is a full water molecule, not a lone proton. This is a Knowledge of Scientific Concepts and Principles question because you must recall that peptide bond formation is a dehydration (condensation) reaction that releases water.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 70)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'process_step_confusion', NULL FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', NULL FROM q
  UNION ALL
