-- Q2 [Peptide Bond Formation & Hydrolysis] easy skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Peptide Bond Formation & Hydrolysis', 'A biochemist characterizes a newly isolated, unbranched single-chain peptide and determines that it is composed of exactly seven amino acid residues joined end to end. Based on this information, how many peptide bonds most likely link the residues of this linear heptapeptide?', '[{"label": "A", "text": "Six peptide bonds"}, {"label": "B", "text": "Seven peptide bonds"}, {"label": "C", "text": "Five peptide bonds"}, {"label": "D", "text": "Eight peptide bonds"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because each peptide (amide) bond joins one adjacent pair of residues, so a linear chain of \(N\) residues has \(N-1\) such links. LibreTexts states that "the resulting structure is called a dipeptide when an amide bond links two amino acids," i.e., two residues are joined by one bond; adding each additional residue creates exactly one more amide link (LibreTexts 3.1). Because forming the bond is a dehydration reaction, OpenStax notes that the bond links "the carboxyl end of one amino acid with the amino end of another, producing one water molecule during the process," confirming one bond per adjacent pair. For an unbranched heptapeptide, \(N=7\), so the number of peptide bonds is \(7-1=6\). (Choice A) is correct: a linear seven-residue chain has six junctions between adjacent residues, and each junction is one peptide bond, giving \(7-1=6\). (Choice B) is wrong: seven counts the residues themselves, not the bonds; a chain of \(N\) residues has only \(N-1\) internal links because the two end residues each contribute a free terminus rather than a bond. (Choice C) is wrong: five would be \(N-2\), which under-counts by one and would describe a six-residue (hexapeptide) chain, not a heptapeptide. (Choice D) is wrong: eight is \(N+1\); a linear peptide cannot have more bonds than \(N-1\) unless it were branched or cyclic, and the chain here is explicitly unbranched and single-chain. This is a Scientific Reasoning and Problem Solving question because you must apply the \(N-1\) relationship between residue count and peptide-bond count to a specific linear chain length.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 70)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'scale_unit_error', 'off_by_one_counted_residues_not_bonds' FROM q
