-- Q3 [Peptide Bond Formation & Hydrolysis] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Peptide Bond Formation & Hydrolysis', 'A protease cleaves the single peptide bond of the dipeptide Ser-Val, releasing free serine and free valine. As this amide linkage is broken, how does the reaction account for water relative to the dehydration synthesis that originally formed the bond?', '[{"label": "A", "text": "One molecule of water is released"}, {"label": "B", "text": "Two molecules of water are consumed"}, {"label": "C", "text": "One molecule of water is consumed"}, {"label": "D", "text": "No net water is gained or lost"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because hydrolysis is the exact reverse of the dehydration synthesis (condensation) that built the peptide bond: where bond formation released one \(\text{H}_2\text{O}\), cleaving that one amide bond incorporates one \(\text{H}_2\text{O}\) to separate the two residues. The textbook states that amino acids are linked by a ''dehydration synthesis (loss of water) reaction'' and that ''the reverse reaction, hydrolysis, requires the incorporation of a water molecule to separate two amino acids and break the amide bond.'' Because Ser-Val contains exactly one peptide bond, exactly one water is consumed to regenerate the free \(-\text{COO}^-\) and \(-\text{NH}_3^+\) termini. (Choice A) describes condensation, not hydrolysis; releasing water is what happens when the bond forms, so it reverses the actual direction of cleavage. (Choice B) overcounts: a dipeptide has only one peptide bond, so only one water can be added, not two. (Choice C) is correct: breaking the single amide bond by hydrolysis consumes one molecule of water, the mirror image of the single water lost during synthesis. (Choice D) ignores that the bond-breaking step is itself a hydrolysis, which by definition incorporates a water molecule rather than balancing out to zero. This is a Scientific Reasoning and Problem Solving question because you must apply the principle that hydrolysis reverses condensation to determine the direction and stoichiometry of water for a specific dipeptide.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', NULL FROM q
  UNION ALL
  SELECT id, 'B', 'scale_unit_error', NULL FROM q
  UNION ALL
