-- Q5 [Primary Structure] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Primary Structure', 'A biochemist examines the linear pentapeptide Ser-Val-Ala-Thr-Leu, drawn in the conventional N-to-C direction. The serine residue at the left end of this chain bears a free \(\alpha\)-amino group that is not involved in any peptide bond. This terminus of the peptide is known as the:', '[{"label": "A", "text": "C-terminus, bearing a free \\(\\alpha\\)-carboxyl group"}, {"label": "B", "text": "N-terminus, bearing a free \\(\\alpha\\)-amino group"}, {"label": "C", "text": "C-terminus, bearing a free \\(\\alpha\\)-amino group"}, {"label": "D", "text": "N-terminus, bearing a free \\(\\alpha\\)-carboxyl group"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because a protein''s primary structure is the amino acid sequence written from N- to C-terminal, and the residue at the N-terminus retains a free \(\alpha\)-amino group that is not tied up in a peptide bond. The textbook states that proteins are "written from N- to C-terminal" (LibreTexts 3.2.2) and that "the amino group of the N-terminal amino acid and the carboxyl group of the C-terminal amino acid of a protein may be charged" (LibreTexts 3.1.10), confirming that the free \(\alpha\)-amino group belongs to the N-terminus while the free \(\alpha\)-carboxyl group belongs to the C-terminus. Because the conventional drawing places the N-terminus on the left, the serine bearing the free \(-\text{NH}_3^+\) group is the N-terminal residue. (Choice A) is incorrect because the C-terminus is the opposite end, bearing the free \(\alpha\)-carboxyl group, not the free amino group described. (Choice B) is correct: the leftmost residue with a free \(\alpha\)-amino group is the N-terminus by definition. (Choice C) names the correct functional group but the wrong terminus, since a free \(\alpha\)-amino group defines the N-terminus, not the C-terminus. (Choice D) names the correct terminus but the wrong functional group, since the N-terminus carries a free \(\alpha\)-amino group, whereas the free \(\alpha\)-carboxyl group is found at the C-terminus. This is a Knowledge of Scientific Concepts and Principles question because you must recall how the ends of a peptide are named and which free functional group each terminus bears.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 70)
  RETURNING id
)
