-- Q6 [Peptide Bond Formation & Hydrolysis] easy skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Peptide Bond Formation & Hydrolysis', 'A researcher records a newly isolated pentapeptide using the standard convention for writing a primary sequence, noting it as Ser-Gly-Asp-Phe-Thr. Which residue carries the peptide''s free \(\alpha\)-amino \(-\text{NH}_3^+\) group at its N-terminus?', '[{"label": "A", "text": "The threonine residue"}, {"label": "B", "text": "The phenylalanine residue"}, {"label": "C", "text": "The serine residue"}, {"label": "D", "text": "The aspartate residue"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because, by convention, a protein''s primary structure is written and read from the N-terminus to the C-terminus, left to right; the LibreTexts text states that "A protein''s primary (1o) structure is simply the amino acid sequence of a protein written from N- to C-terminal" (line 6493). Therefore the leftmost residue in Ser-Gly-Asp-Phe-Thr is the N-terminal residue bearing the free \(\alpha\)-amino group, which is serine. The text further notes that proteins are synthesized "starting with the amino terminus and ending with the carboxy terminus" (lines 6412-6413), so the free \(\alpha\)-amino end is at the start of the written sequence. (Choice A) is incorrect: threonine is the rightmost residue, which is the C-terminus bearing the free \(\alpha\)-carboxyl \(-\text{COO}^-\) group, not the free \(\alpha\)-amino group. (Choice B) is incorrect: phenylalanine sits internally in the chain (an aromatic residue and a chymotrypsin cleavage site, since chymotrypsin cleaves on the C-side of aromatic residues per line 9931), and its \(\alpha\)-amino group is locked in a peptide bond, not free. (Choice C) is correct: serine is written leftmost, marking the N-terminus with the free \(\alpha\)-amino group. (Choice D) is incorrect: aspartate is an internal residue whose free carboxyl is on its side chain, not the \(\alpha\)-amino terminus; its backbone amino group is engaged in a peptide bond. This is a Knowledge of Scientific Concepts and Principles question because you must recall the N-to-C convention for writing and reading a peptide''s primary sequence and apply it to locate the free \(\alpha\)-amino terminus.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
