-- Q7 [Peptide Bond Formation & Hydrolysis] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Peptide Bond Formation & Hydrolysis', 'During the bottom-up mass-spectrometry workup of a protein, a researcher needs a protease that cleaves the polypeptide on the carboxyl side of the basic residues arginine and lysine. Which enzyme has this specificity?', '[{"label": "A", "text": "Trypsin"}, {"label": "B", "text": "Chymotrypsin"}, {"label": "C", "text": "Elastase"}, {"label": "D", "text": "Pepsin"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because trypsin cleaves the peptide bond on the carboxyl side of the basic residues lysine and arginine. The LibreTexts source states that "Trypsin cleaves proteins on the carboxylic side of basic residues, such as lysine and arginine, while chymotrypsin cleaves after aromatic hydrophobic amino acids, such as phenylalanine, tyrosine, and tryptophan" and elsewhere describes "trypsin, which cleaves on the carboxyl side of Lys and Arg residues." The basic side chains of Arg and Lys, which carry a \(-\text{NH}_3^+\) or guanidinium charge at physiological pH, fit the negatively charged S1 binding pocket of trypsin, giving it this specificity. (Choice A) is correct: trypsin is the protease that cleaves on the carboxyl side of the basic residues arginine and lysine. (Choice B) is wrong because chymotrypsin cleaves after the aromatic hydrophobic residues phenylalanine, tyrosine, and tryptophan, not the basic residues. (Choice C) is wrong because elastase cleaves after small, hydrophobic residues like glycine, alanine, and valine. (Choice D) is wrong because pepsin is a gastric protease that acts in the stomach''s acidic environment and does not have the trypsin specificity for the basic residues Arg and Lys. This is a Knowledge of Scientific Concepts and Principles question because you must recall the established cleavage specificity of trypsin for the basic residues arginine and lysine.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
