-- Q8 [Peptide Bond Formation & Hydrolysis] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Peptide Bond Formation & Hydrolysis', 'A biochemist incubates the pentapeptide Ala-Gly-Tyr-Ser-Lys with purified chymotrypsin under conditions that allow complete digestion. At which position does chymotrypsin hydrolyze a peptide bond in this substrate?', '[{"label": "A", "text": "On the carboxyl side of Lys"}, {"label": "B", "text": "On the carboxyl side of Tyr"}, {"label": "C", "text": "On the carboxyl side of Gly"}, {"label": "D", "text": "On the amino side of Tyr"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because chymotrypsin cleaves peptide bonds on the carboxyl side of aromatic residues. In the source, "chymotrypsin cleaves after aromatic hydrophobic amino acids, such as phenylalanine, tyrosine, and tryptophan," because its S1 binding pocket "is large and hydrophobic, accommodating the substrate''s aromatic residues." Tyrosine (Tyr) is the only aromatic residue in Ala-Gly-Tyr-Ser-Lys, so chymotrypsin hydrolyzes the Tyr-Ser bond, splitting the peptide into Ala-Gly-Tyr and Ser-Lys. The textbook''s worked example confirms this carboxyl-side rule: "Since chymotrypsin cleaves aromatic amino acids at the C-terminus," the fragment APITALY ends at its tyrosine. (Choice A) is incorrect: cleavage on the carboxyl side of the basic residue Lys is the specificity of trypsin, which "cleaves proteins on the carboxylic side of basic residues, such as lysine and arginine," not chymotrypsin. (Choice C) is incorrect: cleavage after the small residue Gly reflects elastase, which "cleaves after small, hydrophobic residues like glycine, alanine, and valine," a different protease. (Choice B) is correct: Tyr is aromatic, and chymotrypsin hydrolyzes on the carboxyl (C-terminal) side of such residues. (Choice D) is incorrect: chymotrypsin cleaves on the carboxyl side, not the amino side, of its target residue, so the bond C-terminal to Tyr (Tyr-Ser), not the Gly-Tyr bond preceding it, is broken. This is a Scientific Reasoning and Problem Solving question because you must apply chymotrypsin''s documented aromatic-residue specificity to a specific sequence and predict the exact bond that is hydrolyzed.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
