-- Q9 [Peptide Bond Formation & Hydrolysis] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Peptide Bond Formation & Hydrolysis', 'A researcher exposes the heptapeptide Ala-Lys-Gly-Phe-Arg-Ser-Glu (written N-terminus to C-terminus) to purified trypsin under conditions favoring complete digestion. Assuming trypsin cleaves with full specificity, which set of fragments is recovered?', '[{"label": "A", "text": "Two fragments: Ala-Lys-Gly-Phe and Arg-Ser-Glu"}, {"label": "B", "text": "Three fragments: Ala, Lys-Gly-Phe, and Arg-Ser-Glu"}, {"label": "C", "text": "Four fragments: Ala-Lys, Gly-Phe, Arg, and Ser-Glu"}, {"label": "D", "text": "Three fragments: Ala-Lys, Gly-Phe-Arg, and Ser-Glu"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because trypsin cleaves a peptide on the carboxyl (C-terminal) side of the basic residues lysine and arginine. The textbook states that "Trypsin cleaves proteins on the carboxylic side of basic residues, such as lysine and arginine" and that trypsin "cleaves on the carboxyl side of Lys and Arg residues." Reading Ala-Lys-Gly-Phe-Arg-Ser-Glu from N to C, the only basic residues are Lys (position 2) and Arg (position 5); cutting after each yields exactly three fragments: Ala-Lys, Gly-Phe-Arg, and Ser-Glu. The aromatic Phe is a chymotrypsin target, not a trypsin target, so the peptide bond on its C-side stays intact. (Choice A) is incorrect because cleaving only after the aromatic Phe applies chymotrypsin specificity ("chymotrypsin cleaves after aromatic hydrophobic amino acids, such as phenylalanine, tyrosine, and tryptophan"), not trypsin''s. (Choice B) is incorrect because it cleaves on the N-terminal side of the basic residues; trypsin cleaves on the carboxyl side, so this reverses the cut position and misassigns the fragment identities. (Choice C) is incorrect because it over-cleaves by cutting after both the basic residues and the aromatic Phe, combining trypsin and chymotrypsin specificities into one digest. (Choice D) is correct: cleavage on the C-side of Lys and Arg alone leaves the Phe bond intact and produces Ala-Lys, Gly-Phe-Arg, and Ser-Glu. This is a Scientific Reasoning and Problem Solving question because you must apply trypsin''s defined cleavage rule to a specific sequence and predict the resulting fragments.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 150)
  RETURNING id
)
