-- Q10 [Peptide Bond Formation & Hydrolysis] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Peptide Bond Formation & Hydrolysis', 'A researcher incubates the heptapeptide Ala-Phe-Gly-Lys-Trp-Ser-Val (written N-terminus to C-terminus) with purified chymotrypsin until digestion is complete. Which set of fragments is recovered?', '[{"label": "A", "text": "Ala-Phe-Gly-Lys + Trp-Ser-Val"}, {"label": "B", "text": "Ala + Phe-Gly-Lys + Trp-Ser-Val"}, {"label": "C", "text": "Ala-Phe + Gly-Lys-Trp + Ser-Val"}, {"label": "D", "text": "Ala-Phe-Gly-Lys-Trp + Ser-Val"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because chymotrypsin is a protease that hydrolyzes a peptide bond on the carboxyl (C-terminal) side of an aromatic residue — phenylalanine, tryptophan, or tyrosine (LibreTexts line 29347: "chymotrypsin cleaves after aromatic hydrophobic amino acids, such as phenylalanine, tyrosine, and tryptophan"). In Ala-Phe-Gly-Lys-Trp-Ser-Val the aromatic residues are Phe (position 2) and Trp (position 5), so cleavage occurs after Phe and after Trp, splitting the chain into Ala-Phe, Gly-Lys-Trp, and Ser-Val. The basic residue Lys is left intact because chymotrypsin does not act on it. (Choice A) is incorrect: cleaving only after Lys applies trypsin''s specificity — trypsin "cleaves on the carboxyl side of Lys and Arg residues" (LibreTexts line 8717), not chymotrypsin''s. (Choice B) is incorrect: it places the cut on the amino (N-terminal) side of each aromatic residue, but chymotrypsin hydrolyzes the bond on the carboxyl side of the recognized residue (LibreTexts line 29347, worked example lines 9931-9934). (Choice C) is correct: chymotrypsin hydrolyzes the bond C-terminal to both Phe and Trp, yielding three fragments. (Choice D) is incorrect: it cleaves after Trp but overlooks Phe, recognizing only one of the two aromatic residues; Phe is also a chymotrypsin target (LibreTexts line 29347). This is a Scientific Reasoning and Problem Solving question because you must apply chymotrypsin''s known specificity to a defined sequence and predict the resulting hydrolysis fragments.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 150)
  RETURNING id
)
