-- Q11 [Primary Structure] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Primary Structure', 'A biochemist describes the primary structure of a newly sequenced protein as its linear ordering of amino acid residues. Within this linear sequence, adjacent residues are held together by which type of covalent bond?', '[{"label": "A", "text": "A hydrogen bond between backbone atoms"}, {"label": "B", "text": "A peptide (amide) bond"}, {"label": "C", "text": "A disulfide bond between cysteine residues"}, {"label": "D", "text": "A phosphodiester bond"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because the primary structure of a protein is its linear amino acid sequence, in which consecutive residues are joined by covalent peptide bonds. The textbook defines the peptide bond as "the amide linkage between amino acids in a protein," formed by dehydration synthesis between the \(\alpha\)-carboxyl group of one residue and the \(\alpha\)-amine of the next (LibreTexts 6411, 5123). It also lists "primary structure: the linear amino acid sequence of a protein" as the level of organization built from these covalent amide links (LibreTexts 6609). (Choice A) A hydrogen bond between backbone amide H and carbonyl O atoms defines secondary structure, not the covalent linkage joining residues in the sequence, and such H-bonds are non-covalent (LibreTexts 6610-6611). (Choice B) is correct: residues in the primary sequence are connected by the covalent peptide (amide) bond. (Choice C) Disulfide bonds form between two cysteine side chains and stabilize tertiary and quaternary structure; they do not link adjacent residues along the backbone (LibreTexts 6613, 5892). (Choice D) A phosphodiester bond links nucleotides in nucleic acids, not amino acids in a protein (LibreTexts 6610, 31806). This is a Knowledge of Scientific Concepts and Principles question because you must recall that the linear amino acid sequence of a protein''s primary structure is held together by covalent peptide (amide) bonds.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
