-- Q12 [Primary Structure] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Primary Structure', 'A researcher compares the same enzyme isolated from two individuals and finds that the two versions are identical in length but differ in the identity of the amino acid at position 47. Assuming both chains are translated normally, the difference in this position of the linear sequence is most directly determined by:', '[{"label": "A", "text": "The DNA-derived mRNA codon read at that position"}, {"label": "B", "text": "Backbone hydrogen bonding within the \\(\\alpha\\)-helix"}, {"label": "C", "text": "The protonation state of that residue''s side chain"}, {"label": "D", "text": "Chymotrypsin cleavage at an upstream aromatic residue"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because the primary sequence—the specific order and identity of amino acids in a protein—is dictated by the genetic information encoded in mRNA, which is in turn encoded in the genomic DNA. The textbook states that as amino acids are linked into a specific protein, "they are arranged in an order dictated by the genetic information encoded in messenger RNA (mRNA)" and that "the mRNA sequences are encoded in the genomic DNA sequence," so the codon read at a given position determines which residue is inserted there. A difference in the amino acid at position 47 between two otherwise-normal chains therefore traces most directly to a difference in the DNA-derived codon at that position. (Choice A) is correct: the codon read from the DNA-derived mRNA selects the identity of the residue at each position of the primary sequence. (Choice B) is wrong because backbone hydrogen bonding within an \(\alpha\)-helix is secondary structure—a downstream consequence of the sequence, held together "between amide Hs and carbonyl Os within a single continuous strand"—and does not set which amino acid occupies a position. (Choice C) is wrong because the protonation state of a side chain reflects local pH and pKa and changes a residue''s charge, not its identity or its encoded position in the chain. (Choice D) is wrong because chymotrypsin is a protease that hydrolyzes peptide bonds on the C-side of aromatic residues after synthesis; proteolysis can shorten a chain but does not dictate the genetically encoded order of residues in a normally translated protein. This is a Scientific Reasoning and Problem Solving question because you must apply the relationship between genetic information and primary sequence to infer the source of an observed single-position difference.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
