-- Q14 [Primary Structure] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Primary Structure', 'A research team has purified a novel 28-residue peptide hormone and wants to establish its primary structure. Which experimental approach directly yields the linear order of amino acids in the peptide?', '[{"label": "A", "text": "Quantitative amino acid composition analysis"}, {"label": "B", "text": "Circular dichroism spectroscopy of the peptide"}, {"label": "C", "text": "Edman degradation from the N-terminus"}, {"label": "D", "text": "Trypsin digestion followed by gel electrophoresis"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because primary structure is the unique linear sequence of amino acids, and Edman degradation is the classical chemical method that determines that sequence by labeling and cleaving the amino-terminal residue one at a time without disrupting the remaining peptide bonds, identifying each residue as its PTH-derivative before repeating the cycle (LibreTexts 3.4.3.1: "the amino-terminal residue is labeled and cleaved from the peptide without disrupting the peptide bonds between other amino acid residues"). Because the peptide is only 28 residues, it falls within the ~30-residue practical limit of a single Edman run, so the full order can be read directly from the N-terminus. (Choice A) is incorrect: quantitative amino acid analysis hydrolyzes the protein completely and reports only how much of each amino acid is present — the source states plainly that "the amino acid composition does not determine the protein''s sequence," so it gives counts, not order. (Choice B) is incorrect: circular dichroism reports secondary structure by distinguishing \(\alpha\)-helices, \(\beta\)-sheets, and random coils, not the linear residue sequence. (Choice C) is correct: Edman degradation sequentially removes and identifies N-terminal residues to read the amino-acid order, directly establishing primary structure. (Choice D) is incorrect: trypsin cleaves on the carboxyl side of the basic residues Lys and Arg, generating fragments whose sizes can be separated by electrophoresis, but fragmentation alone does not reveal the residue order within or across the fragments. This is a Scientific Reasoning and Problem Solving question because you must apply the definition of primary structure to select the technique whose output (residue order) actually matches the experimental goal, distinguishing it from methods that report composition or higher-order structure.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
