-- Q15 [Primary Structure] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Primary Structure', 'A researcher records a synthetic tripeptide in her notebook as Ser-Lys-Phe, following the convention of writing the sequence from the N-terminal residue to the C-terminal residue. Which of the following descriptions identifies the SAME peptide?', '[{"label": "A", "text": "Phenylalanine bears the free \\(-\\text{NH}_3^+\\) terminus"}, {"label": "B", "text": "Serine bears the free \\(-\\text{NH}_3^+\\) terminus"}, {"label": "C", "text": "The sequence Phe-Lys-Ser written N-to-C"}, {"label": "D", "text": "Lysine bears the free \\(-\\text{COO}^-\\) terminus"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because primary structure is written and read from the N-terminal residue (the residue with the free \(\alpha\)-amino group) to the C-terminal residue (the residue with the free \(\alpha\)-carboxyl group). In Ser-Lys-Phe, serine is listed first, so serine is the N-terminus and carries the free \(-\text{NH}_3^+\) group, while phenylalanine is listed last and carries the free \(-\text{COO}^-\) group. LibreTexts states that ''a protein''s primary structure is simply the amino acid sequence of a protein written from N- to C-terminal'' and that ''the amino group of the N-terminal amino acid and the carboxyl group of the C-terminal amino acid of a protein may be charged.'' Because the order of residues is directional, reversing it describes a chemically distinct peptide. (Choice A) is incorrect because phenylalanine is listed last and is therefore the C-terminus bearing the free \(-\text{COO}^-\) group, not the free \(-\text{NH}_3^+\) terminus. (Choice B) is correct: serine is listed first in the N-to-C sequence, so it is the N-terminal residue with the free \(-\text{NH}_3^+\) group. (Choice C) is incorrect because Phe-Lys-Ser is the reverse order; since sequences are directional, this describes a different peptide with phenylalanine at the N-terminus and serine at the C-terminus. (Choice D) is incorrect because lysine is the internal residue; its \(\alpha\)-amino and \(\alpha\)-carboxyl groups are both tied up in peptide bonds, so it bears neither free terminus (only its side chain remains ionizable). This is a Scientific Reasoning and Problem Solving question because you must apply the N-to-C reading convention to a given sequence to deduce which residue occupies each terminus and recognize that reversing the order yields a different molecule.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
