-- Q16 [Primary Structure] hard skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Primary Structure', 'A researcher characterizing a newly translated polypeptide wants to catalog only those features that are established at the level of primary structure. Which of the following features belong to the primary structure of the polypeptide?

I. The covalent peptide (amide) bonds that join each residue to the next
II. The backbone hydrogen bonds between a carbonyl oxygen and an amide hydrogen
III. The directional N-terminus-to-C-terminus order of the residues', '[{"label": "A", "text": "I and III only"}, {"label": "B", "text": "I only"}, {"label": "C", "text": "II and III only"}, {"label": "D", "text": "III only"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because primary structure is defined as the linear amino-acid sequence held together by covalent peptide bonds, including the order in which the residues are arranged. The textbook defines primary structure as ''the linear amino acid sequence of a protein'' and states that ''the primary sequence and covalent peptide bonds establish the framework for protein folding.'' Because proteins are synthesized directionally ''starting with the amino terminus and ending with the carboxy terminus,'' the N-to-C order of residues is part of that linear sequence (statements I and III). The backbone hydrogen bonding in statement II is the defining feature of secondary structure, not primary structure: ''the secondary structure is the repetitive structure formed from H-bonds among backbone amide H and carbonyl O atoms.'' (Choice A) is correct: statements I and III are both primary-structure features (covalent peptide bonds and the directional linear order of residues), while II is excluded. (Choice B) is incorrect because it omits statement III; the N-to-C ordering of residues is part of the linear sequence and therefore part of primary structure, not a separate folding-level property. (Choice C) is incorrect because statement II describes backbone H-bonding, which is the hallmark of secondary structure rather than primary structure. (Choice D) is incorrect because it omits statement I; the covalent peptide bonds are the central covalent linkage that defines primary structure. This is a Knowledge of Scientific Concepts and Principles question because you must recall the definitions that separate primary structure (covalent peptide bonds and the directional linear sequence) from the hydrogen-bonded patterns of secondary structure.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 150)
  RETURNING id
)
